const CACHE = "gvdg-club-v370";
// Member and public app screens past initial load are content-hashed chunks. They live in their own cache,
// which keeps the chunks of this version and the one before it, so a page that was open across an update
// can still open its screens (online or offline) after their files are gone from the server.
const CHUNK_CACHE = "gvdg-member-chunks";
const PUBLIC_CHUNK_CACHE = "gvdg-public-chunks";
const APP_WINDOWS_CACHE = "gvdg-app-windows";
const CHUNK_MANIFEST = "member-chunk-manifest/";
const PUBLIC_CHUNK_MANIFEST = "public-chunk-manifest/";
// Generated by the members and public builds: self.GVDG_MEMBER_CHUNKS / self.GVDG_PUBLIC_CHUNKS.
if (typeof importScripts === "function") {
  importScripts("members-app/sw-chunks.js");
  try {
    importScripts("public-app/sw-chunks.js");
  } catch {}
}
const MEMBER_CHUNKS = Array.isArray(self.GVDG_MEMBER_CHUNKS) ? self.GVDG_MEMBER_CHUNKS : [];
const PUBLIC_CHUNKS = Array.isArray(self.GVDG_PUBLIC_CHUNKS) ? self.GVDG_PUBLIC_CHUNKS : [];
const chunkListId = (list) => [...list.join("|")].reduce((hash, char) => (Math.imul(hash, 31) + char.charCodeAt(0)) >>> 0, 7).toString(36);
// One record per chunk list, so two builds that share a cache name still keep each other's files.
const CHUNK_LIST_ID = chunkListId(MEMBER_CHUNKS);
const PUBLIC_CHUNK_LIST_ID = chunkListId(PUBLIC_CHUNKS);
const OFFLINE_PAGE = "gvdg-members.html";
const ASSETS = [
  "tokens.css",
  "public-polish.css",
  "camera.css",
  "img/fonts/archivo.woff2",
  "img/fonts/archivo-latin-2.woff2",
  "img/fonts/bebas-neue.woff2",
  "watch-pairing.css",
  "phone-activity.css",
  "score-polish.css",
  "member-surfaces.css",
  "member-archive.css",
  "admin-polish.css",
  "homepage-polish.css",
  "home-polish-sections.css",
  "scoring-app.html",
  "scoring-app.css",
  "field-test.css",
  "site.webmanifest",
  "pwa.js",
  "boot-rescue.js",
  "admin-app/admin-app.js",
  "home-app/home-app.js",
  "public-app/public-app.js",
  "tee-sign-preview-app/tee-sign-preview-app.js",
  "img/logo-mark-234.png",
  "img/logo-small.png",
  "img/icons/app-icon-192.png",
  "img/icons/app-icon-512.png",
  "img/icons/maskable-icon-512.png",
  "img/icons/apple-touch-icon.png",
  OFFLINE_PAGE,
  "members-app/members-app.js",
  "score.html",
  "score-app/score-app.js",
  // Loaded only in field test mode; precached so a volunteer's offline reload still records.
  "score-app/field-test-recorder.js"
];
const STATIC_DESTINATIONS = new Set(["script", "style", "image", "font", "manifest"]);

function cacheable(res) {
  return res && res.ok && res.status === 200 && res.type === "basic";
}

// Cloudflare Pages answers a file it doesn't have with the site's HTML and a 200, so "ok" isn't enough: a script must
// come back as a script, a stylesheet as a stylesheet, and nothing else as the HTML page. Otherwise a miss during a
// deploy is saved in place of the real file and served from then on (the owner's Account screen never loaded again).
function rightType(res, url) {
  const type = String(res.headers.get("content-type") || "").toLowerCase();
  const path = url.pathname;
  if (/\.m?js$/i.test(path)) return type.includes("javascript");
  if (/\.css$/i.test(path)) return type.includes("css");
  if (/\.html?$/i.test(path) || path.endsWith("/")) return true;
  return !type.startsWith("text/html");
}

function cacheableAt(res, url) {
  return cacheable(res) && rightType(res, url);
}

// Throw out any saved copy that isn't what its name says (an HTML page saved as a script during a deploy).
async function dropWrongTypes() {
  for (const name of [CACHE, CHUNK_CACHE, PUBLIC_CHUNK_CACHE]) {
    const cache = await caches.open(name);
    for (const request of await cache.keys()) {
      const url = new URL(request.url);
      if (url.pathname.includes("/" + CHUNK_MANIFEST) || url.pathname.includes("/" + PUBLIC_CHUNK_MANIFEST)) continue;
      const saved = await cache.match(request);
      if (saved && !rightType(saved, url)) await cache.delete(request);
    }
  }
}

function staticAsset(req, url) {
  return STATIC_DESTINATIONS.has(req.destination) || /\.(?:avif|css|gif|ico|jpe?g|mjs|js|png|svg|webmanifest|webp|woff2)$/i.test(url.pathname);
}

function isCodeAsset(req, url) {
  return req.destination === "script" || req.destination === "style" || req.destination === "manifest"
    || /\.(?:mjs|js|css|webmanifest)$/i.test(url.pathname);
}

self.addEventListener("install", (event) => {
  event.waitUntil((async () => {
    await dropWrongTypes().catch(() => {});
    const cache = await caches.open(CACHE);
    await Promise.all(ASSETS.map(async (asset) => {
      try {
        const res = await fetch(asset, { cache: "reload" });
        if (res && res.ok && rightType(res, new URL(asset, self.location.href))) await cache.put(asset, res);
      } catch {
      }
    }));
    await Promise.all([
      precacheChunks(CHUNK_CACHE, CHUNK_MANIFEST, CHUNK_LIST_ID, MEMBER_CHUNKS),
      precacheChunks(PUBLIC_CHUNK_CACHE, PUBLIC_CHUNK_MANIFEST, PUBLIC_CHUNK_LIST_ID, PUBLIC_CHUNKS),
    ]);
    await self.skipWaiting();
  })());
});

async function precacheChunks(cacheName, manifestPrefix, listId, chunks) {
  const cache = await caches.open(cacheName);
  await Promise.all(chunks.map(async (chunk) => {
    try {
      // A hashed file never changes, so a copy kept from an earlier version is still right (if it really is the script).
      const url = new URL(chunk, self.location.href);
      const kept = await cache.match(chunk);
      if (kept && rightType(kept, url)) return;
      const res = await fetch(chunk, { cache: "reload" });
      if (cacheableAt(res, url)) await cache.put(chunk, res);
    } catch {
    }
  }));
  await cache.put(manifestPrefix + listId, new Response(JSON.stringify({ chunks, at: Date.now() }), {
    headers: { "Content-Type": "application/json" },
  }));
}

// Keep the chunks this version and the previous one list; drop the rest.
async function pruneChunks(cacheName, manifestPrefix, listId) {
  const cache = await caches.open(cacheName);
  const keys = await cache.keys();
  const manifests = [];
  for (const request of keys) {
    if (!new URL(request.url).pathname.includes("/" + manifestPrefix)) continue;
    const res = await cache.match(request);
    const data = res ? await res.json().catch(() => null) : null;
    manifests.push({ request, current: request.url.endsWith("/" + manifestPrefix + listId), at: Number(data?.at) || 0, chunks: Array.isArray(data?.chunks) ? data.chunks : [] });
  }
  manifests.sort((a, b) => Number(b.current) - Number(a.current) || b.at - a.at);
  const kept = manifests.slice(0, 2);
  const keep = new Set(kept.flatMap((manifest) => manifest.chunks.map((chunk) => new URL(chunk, self.location.href).href)));
  for (const manifest of manifests.slice(2)) await cache.delete(manifest.request);
  for (const request of keys) {
    if (new URL(request.url).pathname.includes("/" + manifestPrefix)) continue;
    if (!keep.has(request.url)) await cache.delete(request);
  }
}

async function cachedChunk(cacheName, req) {
  const cache = await caches.open(cacheName);
  const url = new URL(req.url);
  const cached = await cache.match(req, { ignoreSearch: true });
  if (cached && rightType(cached, url)) return cached;
  if (cached) await cache.delete(req, { ignoreSearch: true }).catch(() => {});
  const res = await fetch(req);
  if (cacheableAt(res, url)) cache.put(req, res.clone()).catch(() => {});
  return rightType(res, url) ? res : Response.error();
}

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((key) => key !== CACHE && key !== CHUNK_CACHE && key !== PUBLIC_CHUNK_CACHE && key !== APP_WINDOWS_CACHE && key !== "gvdg-maps-v2").map((key) => caches.delete(key))))
      .then(() => dropWrongTypes().catch(() => {}))
      .then(() => Promise.all([
        pruneChunks(CHUNK_CACHE, CHUNK_MANIFEST, CHUNK_LIST_ID),
        pruneChunks(PUBLIC_CHUNK_CACHE, PUBLIC_CHUNK_MANIFEST, PUBLIC_CHUNK_LIST_ID),
      ]).catch(() => {}))
      .then(() => self.clients.claim())
  );
});

const appClients = new Set();

const APP_WINDOW_PREFIX = "/_sw/app-window/";

async function recordAppWindow(clientId) {
  if (!clientId || typeof caches?.open !== "function") return;
  try {
    const cache = await caches.open(APP_WINDOWS_CACHE);
    const key = new URL(APP_WINDOW_PREFIX + encodeURIComponent(clientId), self.location.origin).href;
    await cache.put(key, new Response("1"));
  } catch {}
}

async function knownAppWindows(windows) {
  const known = new Set(appClients);
  if (typeof caches?.open === "function") {
    try {
      const cache = await caches.open(APP_WINDOWS_CACHE);
      const reqs = await cache.keys();
      const liveIds = new Set((windows || []).map((win) => win && win.id).filter(Boolean));
      for (const req of reqs) {
        const rawUrl = typeof req === "string" ? req : req.url;
        const path = new URL(rawUrl, self.location.origin).pathname;
        if (!path.startsWith(APP_WINDOW_PREFIX)) continue;
        const id = decodeURIComponent(path.slice(APP_WINDOW_PREFIX.length));
        if (liveIds.has(id)) {
          known.add(id);
        } else {
          await cache.delete(req);
        }
      }
    } catch {}
  }
  return known;
}

self.addEventListener("message", (event) => {
  if (event.data && event.data.type === "SKIP_WAITING") self.skipWaiting();
  if (event.data && event.data.type === "APP_WINDOW" && event.source && event.source.id) {
    appClients.add(event.source.id);
    const work = recordAppWindow(event.source.id);
    if (typeof event.waitUntil === "function") event.waitUntil(work);
  }
});

const MAP_CACHE = "gvdg-maps-v2";
const MAP_REFRESH_MS = 30 * 24 * 60 * 60 * 1000;
const MAP_MAX_ENTRIES = 3000;
let mapPuts = 0;

// Image tags are no-cors, so a failed Esri response would be opaque and get pinned forever: fetch with CORS and keep
// only real images. Every so often the oldest entries go, so the map cache stays a few tens of MB.
async function fetchMap(cache, req) {
  const res = await fetch(req.url, { mode: "cors", credentials: "omit", cache: "no-store" });
  const type = res.headers.get("content-type") || "";
  if (res.ok && type.startsWith("image/")) {
    await cache.put(req, res.clone()).catch(() => {});
    mapPuts += 1;
    if (mapPuts % 50 === 0) trimMaps(cache).catch(() => {});
  }
  return res;
}

async function trimMaps(cache) {
  const keys = await cache.keys();
  if (keys.length <= MAP_MAX_ENTRIES) return;
  await Promise.all(keys.slice(0, keys.length - Math.floor(MAP_MAX_ENTRIES * 0.8)).map((key) => cache.delete(key)));
}

self.addEventListener("fetch", (event) => {
  const req = event.request;
  const url = new URL(req.url);
  if (req.method === "GET" && url.hostname.endsWith("arcgisonline.com") && url.pathname.includes("/World_Imagery/")) {
    // Satellite tiles and pictures: the saved copy straight away (aerial photos hardly change), refreshed in the
    // background once it's MAP_REFRESH_MS old; the network only for what this phone hasn't seen yet.
    event.respondWith((async () => {
      const cache = await caches.open(MAP_CACHE);
      const cached = await cache.match(req);
      if (cached) {
        const saved = Date.parse(cached.headers.get("date") || "");
        if (!Number.isFinite(saved) || Date.now() - saved > MAP_REFRESH_MS) event.waitUntil(fetchMap(cache, req).catch(() => {}));
        return cached;
      }
      try {
        return await fetchMap(cache, req);
      } catch {
        return Response.error();
      }
    })());
    return;
  }
  if (req.method !== "GET" || url.origin !== self.location.origin) return;
  // The API on the site's own address (gvdgclub.com/api/*, the Worker): straight to the network, exactly as when it
  // was another host. Never cached here, never answered with the offline page (the browser's own cache still applies).
  if (url.pathname === "/api" || url.pathname.startsWith("/api/")) return;

  // A notification image fetch has no window. Answer it from the cache and
  // Brave draws its own lion instead of the club mark.
  if (!event.clientId && (url.pathname === "/img/icons/app-icon-192.png" || url.pathname === "/img/icons/notification-badge.png")) return;

  if (req.mode === "navigate" || req.destination === "document") {
    event.respondWith(
      fetch(req)
        .then((res) => {
          if (cacheable(res)) {
            const copy = res.clone();
            caches.open(CACHE).then((cache) => cache.put(req, copy)).catch(() => {});
          }
          return res;
        })
        .catch(async () => {
          const exact = await caches.match(req);
          if (exact) return exact;
          if (url.pathname === "/score.html") {
            const scorer = await caches.match("score.html");
            if (scorer) return scorer;
          }
          if (url.pathname === "/scoring-app.html") {
            const scoringApp = await caches.match("scoring-app.html");
            if (scoringApp) return scoringApp;
          }
          return (await caches.match(OFFLINE_PAGE)) || Response.error();
        })
    );
    return;
  }

  if (!staticAsset(req, url)) return;

  if (url.pathname.includes("/members-app/chunks/")) {
    event.respondWith(cachedChunk(CHUNK_CACHE, req));
    return;
  }

  if (url.pathname.includes("/public-app/chunks/")) {
    event.respondWith(cachedChunk(PUBLIC_CHUNK_CACHE, req));
    return;
  }

  if (isCodeAsset(req, url)) {
    const codeFallback = async () => {
      const exact = await caches.match(req);
      if (exact && rightType(exact, url)) return exact;
      // HTML cache-busters must also work on the first offline scorer visit:
      // install precaches the canonical bundle before any ?v= URL is opened.
      const asset = url.pathname.slice(1);
      if (ASSETS.includes(asset) && [...url.searchParams.keys()].every((key) => key === "v")) {
        const installed = await caches.match(asset);
        if (installed && rightType(installed, url)) return installed;
      }
      return null;
    };
    event.respondWith(
      fetch(req)
        .then(async (res) => {
          if (res.ok && rightType(res, url)) {
            if (cacheableAt(res, url)) {
              const copy = res.clone();
              caches.open(CACHE).then((cache) => cache.put(req, copy)).catch(() => {});
            }
            return res;
          }
          const cached = await codeFallback();
          if (cached) return cached;
          return rightType(res, url) ? res : Response.error();
        })
        .catch(async () => (await codeFallback()) || Response.error())
    );
    return;
  }

  event.respondWith(
    caches.match(req).then((cached) => {
      if (cached && rightType(cached, url)) return cached;
      return fetch(req)
        .then((res) => {
          if (cacheableAt(res, url)) {
            const copy = res.clone();
            caches.open(CACHE).then((cache) => cache.put(req, copy)).catch(() => {});
          }
          return res;
        })
        .catch(() => (req.destination === "image" ? offlineImage(url) : Response.error()));
    })
  );
});

// An image missing offline shows the club logo. The header mark's 1x/2x file falls back to its precached
// 3x file, which draws the same; anything else gets the small full logo.
function offlineImage(url) {
  return caches.match(url.pathname.includes("/img/logo-mark-") ? "img/logo-mark-234.png" : "img/logo-small.png");
}

function adminNotificationUrl(raw) {
  if (typeof raw !== "string" || !raw.startsWith("/admin.html") || raw.startsWith("//") || raw.includes("\\") || raw.includes("://")) {
    return new URL("/admin.html", self.location.origin).href;
  }
  return new URL(raw, self.location.origin).href;
}

function memberNotificationUrl(raw) {
  if (typeof raw === "string" && raw.startsWith("/gvdg-members.html") && !raw.startsWith("//") && !raw.includes("\\") && !raw.includes("://")) {
    return new URL(raw, self.location.origin).href;
  }
  return new URL("/gvdg-members.html", self.location.origin).href;
}

function readPush(event) {
  let data = {};
  try {
    data = event.data ? event.data.json() : {};
  } catch {
    data = {};
  }
  if (!data || typeof data !== "object") data = {};
  return {
    title: typeof data.title === "string" && data.title.trim() ? data.title.trim().slice(0, 80) : "GVDG admin",
    body: typeof data.body === "string" ? data.body.slice(0, 180) : "",
    tag: typeof data.tag === "string" && data.tag.trim() ? data.tag.trim().slice(0, 80) : "gvdg-admin",
    url: typeof data.url === "string" ? data.url : "/admin.html",
    kind: data.kind === "member" ? "member" : "admin",
  };
}

async function openAdmin(target) {
  const all = await self.clients.matchAll({ type: "window", includeUncontrolled: true });
  const alive = new Set(all.map((client) => client.id));
  for (const id of appClients) if (!alive.has(id)) appClients.delete(id);
  const known = await knownAppWindows(all);
  // Only reuse the installed app. A Chrome tab must not catch the tap.
  for (const client of all) {
    if (!known.has(client.id)) continue;
    let url;
    try { url = new URL(client.url); } catch { continue; }
    if (url.origin !== self.location.origin) continue;
    try {
      if (typeof client.navigate === "function") {
        const next = await client.navigate(target);
        if (next && typeof next.focus === "function") return next.focus();
      }
    } catch {
      /* open a fresh app window below */
    }
    if (typeof client.focus === "function") return client.focus();
  }
  if (self.clients.openWindow) return self.clients.openWindow(target);
}

self.addEventListener("push", (event) => {
  const note = readPush(event);
  const icon = new URL("/img/icons/app-icon-192.png", self.location.origin).href;
  const badge = new URL("/img/icons/notification-badge.png", self.location.origin).href;
  event.waitUntil(self.registration.showNotification(note.title, {
    body: note.body,
    tag: note.tag,
    data: { url: note.url, kind: note.kind },
    icon,
    badge,
  }));
});

function rangeNotificationUrl(raw) {
  if (typeof raw === "string" && raw.startsWith("/score.html") && !raw.startsWith("//") && !raw.includes("\\") && !raw.includes("://")) {
    return new URL(raw, self.location.origin).href;
  }
  return new URL("/score.html", self.location.origin).href;
}

async function focusScore(target) {
  const all = await self.clients.matchAll({ type: "window", includeUncontrolled: true });
  const alive = new Set(all.map((client) => client.id));
  for (const id of appClients) if (!alive.has(id)) appClients.delete(id);
  const scores = [];
  for (const client of all) {
    let url;
    try { url = new URL(client.url); } catch { continue; }
    if (url.origin !== self.location.origin) continue;
    if (!url.pathname.endsWith("/score.html")) continue;
    scores.push(client);
  }
  const known = await knownAppWindows(all);
  const installed = scores.find((client) => known.has(client.id));
  const client = installed || scores[0];
  if (client && typeof client.focus === "function") return client.focus();
  if (self.clients.openWindow) return self.clients.openWindow(target);
}

self.addEventListener("notificationclick", (event) => {
  const data = event.notification.data || {};
  if (data.kind === "range" || data.kind === "talk") {
    if (data.kind === "talk") event.notification.close();
    event.waitUntil(focusScore(rangeNotificationUrl(data.url)));
    return;
  }
  event.notification.close();
  if (data.kind === "member") {
    // Applicant "you're approved" push: open the members page in whatever window is available.
    event.waitUntil(self.clients.openWindow ? self.clients.openWindow(memberNotificationUrl(data.url)) : undefined);
    return;
  }
  const target = adminNotificationUrl(data.url);
  event.waitUntil(openAdmin(target));
});
